import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { createSecretKey, KeyObject } from 'crypto';

/**
 * Auth Middleware
 *
 * Verifies JWTs signed with our Supabase JWT secret (HS256).
 * All user tokens are generated by our backend after phone OTP verification.
 */

export interface AuthRequest extends Request {
  user?: {
    id: string;
    email?: string;
    phone?: string;
  };
  isInternal?: boolean;
}

// Cache the secret key object to avoid recreating it on every request
let cachedSecretKey: KeyObject | null = null;

// Get the JWT secret as a KeyObject for HS256 verification
// Must use createSecretKey to ensure jsonwebtoken treats it as symmetric
function getJwtSecret(): KeyObject {
  if (cachedSecretKey) {
    return cachedSecretKey;
  }

  const secret = process.env.SUPABASE_JWT_SECRET;
  if (!secret) {
    throw new Error('Missing SUPABASE_JWT_SECRET environment variable');
  }

  // Create a secret key object from the string
  // This ensures jsonwebtoken recognizes it as a symmetric key
  cachedSecretKey = createSecretKey(Buffer.from(secret));
  return cachedSecretKey;
}

export async function authenticate(
  req: AuthRequest,
  res: Response,
  next: NextFunction
): Promise<void> {
  try {
    // Try API key first (for internal/worker calls)
    const apiKey = req.headers['x-api-key'] as string;
    const expectedKey = process.env.BACKEND_API_KEY;

    if (apiKey && expectedKey && apiKey === expectedKey) {
      req.isInternal = true;
      return next();
    }

    // JWT auth (for user calls)
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).json({ error: 'Missing or invalid authorization header' });
      return;
    }

    const token = authHeader.substring(7);
    const supabaseUrl = process.env.SUPABASE_URL;

    if (!supabaseUrl) {
      res.status(500).json({ error: 'Server configuration error' });
      return;
    }

    // Verify JWT with our secret (HS256)
    const secret = getJwtSecret();

    jwt.verify(
      token,
      secret,
      {
        issuer: `${supabaseUrl}/auth/v1`,
        algorithms: ['HS256'],
      },
      (err, decoded) => {
        if (err) {
          console.error('JWT verification failed:', err.message);
          res.status(401).json({ error: 'Invalid or expired token' });
          return;
        }

        const payload = decoded as jwt.JwtPayload;

        req.user = {
          id: payload.sub!,
          email: payload.email,
          phone: payload.phone,
        };
        req.isInternal = false;

        next();
      }
    );
  } catch (error) {
    console.error('Authentication error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}
